const PptxGenJS = require('pptxgenjs');
const pres = new PptxGenJS();
pres.layout = 'LAYOUT_WIDE';

// Slide 1: Title
const s1 = pres.addSlide();
s1.background = { color: '1B4F72' };
s1.addText('团队协作\n打造高效协同的力量', { x: 0.8, y: 1.5, w: 11, fontSize: 40, bold: true, color: 'FFFFFF', fontFace: '微软雅黑', align: 'center', lineSpacingMultiple: 1.3 });
s1.addText('2024 · 团队管理分享', { x: 0.8, y: 5.5, w: 11, fontSize: 18, color: 'D5E8F0', fontFace: '微软雅黑', align: 'center' });

// Slide 2: Why teamwork matters
const s2 = pres.addSlide();
s2.addText('为什么需要团队协作？', { x: 0.6, y: 0.4, w: 11, fontSize: 30, bold: true, color: '1B4F72', fontFace: '微软雅黑' });
s2.addText(
  '• 复杂问题超出个人能力边界，需要多元视角与技能互补\n' +
  '• 协作能缩短交付周期，提升整体产出效率\n' +
  '• 团队成员互相学习，促进个人成长与创新\n' +
  '• 良好的协作氛围增强归属感，降低人员流失',
  { x: 0.8, y: 1.4, w: 11, fontSize: 20, color: '333333', fontFace: '微软雅黑', lineSpacingMultiple: 1.6 }
);

// Slide 3: Core principles
const s3 = pres.addSlide();
s3.addText('高效协作的核心原则', { x: 0.6, y: 0.4, w: 11, fontSize: 30, bold: true, color: '1B4F72', fontFace: '微软雅黑' });
s3.addText(
  '🎯 目标对齐：确保每个人理解共同目标与自身角色\n\n' +
  '💬 开放沟通：建立透明、及时、双向的信息流动机制\n\n' +
  '🤝 信任与尊重：包容差异，鼓励表达，允许试错\n\n' +
  '📋 责任明确：分工清晰、权责对等，避免灰色地带',
  { x: 0.8, y: 1.3, w: 11, fontSize: 19, color: '333333', fontFace: '微软雅黑', lineSpacingMultiple: 1.4 }
);

// Slide 4: Practical methods
const s4 = pres.addSlide();
s4.addText('落地实践方法', { x: 0.6, y: 0.4, w: 11, fontSize: 30, bold: true, color: '1B4F72', fontFace: '微软雅黑' });
s4.addTable([
  [{ text: '方法', options: { bold: true, color: 'FFFFFF', fill: { color: '1B4F72' }, fontFace: '微软雅黑', fontSize: 16 } },
   { text: '说明', options: { bold: true, color: 'FFFFFF', fill: { color: '1B4F72' }, fontFace: '微软雅黑', fontSize: 16 } }],
  [{ text: '每日站会', options: { fontFace: '微软雅黑', fontSize: 15 } },
   { text: '15分钟同步进展、障碍与计划，保持节奏感', options: { fontFace: '微软雅黑', fontSize: 15 } }],
  [{ text: '看板管理', options: { fontFace: '微软雅黑', fontSize: 15 } },
   { text: '可视化任务流转，让瓶颈一目了然', options: { fontFace: '微软雅黑', fontSize: 15 } }],
  [{ text: '复盘机制', options: { fontFace: '微软雅黑', fontSize: 15 } },
   { text: '定期回顾做得好与待改进之处，形成闭环', options: { fontFace: '微软雅黑', fontSize: 15 } }],
  [{ text: '文档沉淀', options: { fontFace: '微软雅黑', fontSize: 15 } },
   { text: '关键决策与知识写入共享文档，减少信息断层', options: { fontFace: '微软雅黑', fontSize: 15 } }]
], { x: 0.6, y: 1.3, w: 11.5, colW: [3, 8.5], border: { type: 'solid', pt: 0.5, color: 'CCCCCC' }, rowH: [0.5, 0.5, 0.5, 0.5, 0.5] });

// Slide 5: Summary & call to action
const s5 = pres.addSlide();
s5.background = { color: '1B4F72' };
s5.addText('总结与行动', { x: 0.8, y: 0.6, w: 11, fontSize: 32, bold: true, color: 'FFFFFF', fontFace: '微软雅黑', align: 'center' });
s5.addText(
  '✅  以共同目标凝聚方向\n' +
  '✅  用开放沟通消除信息壁垒\n' +
  '✅  靠制度与工具把协作变成习惯\n' +
  '✅  在复盘中持续进化',
  { x: 1.2, y: 1.8, w: 10, fontSize: 22, color: 'FFFFFF', fontFace: '微软雅黑', lineSpacingMultiple: 1.7 }
);
s5.addText('从今天开始，让每一次协作都更进一步！', { x: 0.8, y: 5.2, w: 11, fontSize: 20, bold: true, color: 'F9E79F', fontFace: '微软雅黑', align: 'center' });

pres.writeFile({ fileName: '/workspace/团队协作.pptx' }).then(() => console.log('Done'));

